//! Writes the `layerstack_schemas` tables for a [`Model`].

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;

use layerstack::{PropertyKind, SchemaKind, TokenInterner, Value, Variability};

use crate::model::{Domain, Model, Origin, Property, Schema};

/// The year the generated files' copyright line names. Fixed, so that
/// regenerating from the same sources writes the same files.
const COPYRIGHT_YEAR: u32 = 2026;

/// The generated files, as `(file name, contents)`, with a value this
/// generation cannot express listed as an error.
pub(crate) fn files(model: &Model) -> Result<Vec<(String, String)>, String> {
    let mut types = ValueTypes::default();
    let mut failures = Vec::new();
    let mut files = Vec::new();
    for domain in &model.domains {
        files.push((
            format!("{}.rs", module(domain.plugin)),
            domain_file(model, domain, &mut types, &mut failures),
        ));
    }
    if !failures.is_empty() {
        return Err(format!(
            "values layerstack_schemas cannot express:\n{}",
            failures.join("\n")
        ));
    }
    files.insert(0, ("mod.rs".into(), mod_file(model, &types)));
    Ok(files)
}

/// The header of every generated file.
pub(crate) fn header(model: &Model) -> String {
    format!(
        "// Copyright 2016 Pixar\n\
         // Copyright {COPYRIGHT_YEAR} the LayerStack Authors\n\
         // SPDX-License-Identifier: LicenseRef-TOST-1.0\n\
         //\n\
         // Generated by `layerstack_schemagen` from the schema definitions of OpenUSD\n\
         // {version} (the usd-core {version} wheel, and OpenUSD's source for the\n\
         // plugins the wheel is built without), which are licensed under the\n\
         // Tomorrow Open Source Technology License 1.0; see `LICENSE-TOST-1.0` and\n\
         // `NOTICE`. Do not edit: regenerate with\n\
         // `cargo run -p layerstack_schemagen -- --pxr <site-packages>/pxr \\\n\
         //  --source <OpenUSD checkout>`.\n",
        version = model.version
    )
}

/// The Rust module of a plugin (`usdGeom` → `usd_geom`, `usdUI` →
/// `usd_ui`).
pub(crate) fn module(plugin: &str) -> String {
    let mut out = String::new();
    let mut previous_lower = false;
    for c in plugin.chars() {
        if c.is_ascii_uppercase() && previous_lower {
            out.push('_');
        }
        previous_lower = c.is_ascii_lowercase();
        out.push(c.to_ascii_lowercase());
    }
    out
}

/// A sentence saying where a domain's definitions come from, for one read
/// from the OpenUSD source; empty for the wheel's.
pub(crate) fn origin_note(domain: &Domain) -> String {
    match domain.origin {
        Origin::Wheel => String::new(),
        Origin::Source => format!(
            " From OpenUSD's source (`pxr/usd/{}`); not in the usd-core wheel, which is built \
             without it.",
            domain.plugin
        ),
    }
}

fn mod_file(model: &Model, types: &ValueTypes) -> String {
    let mut out = header(model);
    out.push_str("//\n// Sources:\n");
    for file in &model.files {
        let _ = writeln!(out, "// - `{file}`");
    }
    out.push_str("\n//! The generated tables.\n\n@IMPORTS@\n");
    out.push_str("pub(crate) mod views;\nmod metadata;\n#[cfg(feature = \"usd-shade\")]\npub(crate) mod shader_nodes;\n\n");
    for domain in &model.domains {
        let _ = writeln!(out, "{}\nmod {};", cfg(domain), module(domain.plugin));
    }
    let _ = write!(
        out,
        "\n/// The OpenUSD release whose schemas these are.\n\
         pub const OPENUSD_VERSION: &str = {:?};\n\n",
        model.version
    );

    out.push_str(
        "/// A domain of OpenUSD schemas: the schemas one OpenUSD plugin defines.\n\
         ///\n\
         /// Spec: AOUSD Core §13.1 leaves how schemas are defined to the\n\
         /// implementation; these are OpenUSD's.\n\
         #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]\n\
         #[non_exhaustive]\n\
         pub enum Domain {\n",
    );
    for domain in &model.domains {
        let _ = writeln!(
            out,
            "    /// OpenUSD's `{}` schemas.{}",
            domain.name,
            origin_note(domain)
        );
        if !domain.left_out.is_empty() {
            out.push_str("    ///\n    /// Leaves out, having no prim definition:\n");
            for (name, why) in &domain.left_out {
                let _ = writeln!(out, "    /// - `{name}`, {why}.");
            }
        }
        let _ = writeln!(out, "    {}\n    {},", cfg(domain), domain.variant);
    }
    out.push_str(
        "}\n\nimpl Domain {\n    /// Every domain.\n    pub const ALL: &'static [Self] = &[",
    );
    for domain in &model.domains {
        let _ = write!(out, "{} Self::{}, ", cfg(domain), domain.variant);
    }
    out.push_str(
        "];\n\n    /// The OpenUSD plugin the domain's schemas come from (`usdGeom`).\n    \
         #[must_use]\n    pub fn plugin(self) -> &'static str {\n        match self {\n",
    );
    for domain in &model.domains {
        let _ = writeln!(
            out,
            "            {}\n            Self::{} => {:?},",
            cfg(domain),
            domain.variant,
            domain.name
        );
    }
    out.push_str(
        "        }\n    }\n\n    /// The other domains this domain's schemas or computations need:\n    \
         /// inheritance, built-ins, auto-applies and behavioral dependencies.\n    #[must_use]\n    \
         pub fn dependencies(self) -> &'static [Self] {\n        match self {\n",
    );
    for domain in &model.domains {
        let variants: Vec<String> = domain
            .dependencies
            .iter()
            .map(|plugin| {
                let variant = model
                    .domains
                    .iter()
                    .find(|d| d.plugin == *plugin)
                    .expect("dependency is generated")
                    .variant;
                format!("Self::{variant}")
            })
            .collect();
        let _ = writeln!(
            out,
            "            {}\n            Self::{} => &[{}],",
            cfg(domain),
            domain.variant,
            variants.join(", ")
        );
    }
    out.push_str(
        "        }\n    }\n\n    pub(crate) fn tables(self) -> &'static SchemaTables {\n        match self {\n",
    );
    for domain in &model.domains {
        let _ = writeln!(
            out,
            "            {}\n            Self::{} => &{}::TABLES,",
            cfg(domain),
            domain.variant,
            module(domain.plugin)
        );
    }
    out.push_str("        }\n    }\n}\n");

    for (ident, (name, users)) in &types.statics {
        let features: Vec<String> = users
            .iter()
            .map(|plugin| format!("feature = {:?}", crate::views::feature(plugin)))
            .collect();
        let condition = if features.len() == 1 {
            features[0].clone()
        } else {
            format!("any({})", features.join(", "))
        };
        let _ = write!(
            out,
            "\n#[cfg({condition})]\npub(crate) static {ident}: ValueType = ValueType {{ name: {name:?} }};\n",
        );
    }
    let arc = if out.contains("Arc::from(") {
        "use alloc::sync::Arc;\n\n"
    } else {
        ""
    };
    let value = if out.contains("Value::") {
        "use layerstack::Value;\n\n"
    } else {
        ""
    };
    out.replace(
        "@IMPORTS@\n",
        &format!("{arc}{value}use crate::table::{{SchemaTables, ValueType}};\n\n"),
    )
}

/// The value types the domains declare, each emitted once in `mod.rs`.
#[derive(Default)]
pub(crate) struct ValueTypes {
    /// Static name → (type name, with `[]` for an array, the plugins using
    /// it).
    statics: BTreeMap<String, (String, BTreeSet<&'static str>)>,
}

/// The `#[cfg]` of a domain's feature.
fn cfg(domain: &Domain) -> String {
    format!(
        "#[cfg(feature = {:?})]",
        crate::views::feature(domain.plugin)
    )
}

impl ValueTypes {
    /// Each value type's static, declared with `declaration`
    /// (`static`), for a library's module.
    pub(crate) fn statics(&self, declaration: &str) -> String {
        let mut out = String::new();
        for (ident, (name, _)) in &self.statics {
            let _ = write!(
                out,
                "\n{declaration} {ident}: ValueType = ValueType {{ name: {name:?} }};\n",
            );
        }
        out
    }

    /// The static naming the element type `name`, or its array form when
    /// `is_array`, which `plugin` uses.
    fn get(&mut self, name: &str, is_array: bool, plugin: &'static str) -> String {
        let base = name.strip_suffix("[]").unwrap_or(name);
        let mut ident: String = base.to_ascii_uppercase();
        let mut full = String::from(base);
        if is_array {
            ident.push_str("_ARRAY");
            full.push_str("[]");
        }
        self.statics
            .entry(ident.clone())
            .or_insert((full, BTreeSet::new()))
            .1
            .insert(plugin);
        ident
    }
}

fn domain_file(
    model: &Model,
    domain: &Domain,
    types: &mut ValueTypes,
    failures: &mut Vec<String>,
) -> String {
    let mut out = header(model);
    let _ = write!(
        out,
        "\n//! OpenUSD's `{}` schemas.{}\n\n\
         #![allow(\n    clippy::unreadable_literal,\n    clippy::approx_constant,\n    \
         clippy::excessive_precision,\n    reason = \"values as OpenUSD writes them\"\n)]\n\n\
         @IMPORTS@\n",
        domain.name,
        origin_note(domain)
    );
    let schemas: Vec<&Schema> = domain.schemas.iter().collect();
    out.push_str(&tables(
        "pub(crate) static",
        &schemas,
        &domain.auto_applies,
        &domain.metadata,
        model.tokens(),
        Statics {
            types,
            plugin: domain.plugin,
            prefix: "super::",
        },
        failures,
    ));
    let mut imports = String::new();
    if out.contains("Arc::from(") {
        imports.push_str("use alloc::sync::Arc;\n\n");
    }
    let _ = write!(
        imports,
        "use layerstack::{{{}}};\n\nuse crate::table::{{{}}};\n\n",
        table_imports(&out).0.join(", "),
        table_imports(&out).1.join(", ")
    );
    out.replace("@IMPORTS@\n", &imports)
}

/// The value types a table names, kept once per generated module set.
pub(crate) struct Statics<'t> {
    /// The value types named so far.
    pub(crate) types: &'t mut ValueTypes,
    /// The plugin naming them, for the features of OpenUSD's.
    pub(crate) plugin: &'static str,
    /// The path of the module holding them, from the table's.
    pub(crate) prefix: &'static str,
}

/// The `layerstack` and `table` items `text`, a table, names.
pub(crate) fn table_imports(text: &str) -> (Vec<&'static str>, Vec<&'static str>) {
    let used = |names: &[(&str, &'static str)]| -> Vec<&'static str> {
        names
            .iter()
            .filter(|(marker, _)| text.contains(marker))
            .map(|(_, name)| *name)
            .collect()
    };
    (
        used(&[
            ("PropertyKind::", "PropertyKind"),
            ("SchemaKind::", "SchemaKind"),
            ("Value::", "Value"),
            ("Variability::", "Variability"),
        ]),
        used(&[
            ("SchemaTables {", "SchemaTables"),
            ("Property {", "Property"),
            ("Metadata {", "Metadata"),
            ("Schema {", "Schema"),
            ("fallback(|", "fallback"),
            ("ValueType {", "ValueType"),
        ]),
    )
}

/// The `layerstack_schemas::table::TABLE_FORMAT` the tables are written
/// in. A library module checks it at compile time ([`crate::compile`]'s
/// `--rust`), so this changes with the table types' fields and meaning.
pub(crate) const TABLE_FORMAT: u32 = 1;

/// The `TABLES` static of `schemas`, `auto_applies` and `metadata`,
/// declared with `declaration` (`pub(crate) static`), with a value this
/// generation cannot express listed in `failures`.
pub(crate) fn tables(
    declaration: &str,
    schemas: &[&Schema],
    auto_applies: &[(String, String)],
    metadata: &[layerstack::MetadataDefinition],
    tokens: &TokenInterner,
    statics: Statics<'_>,
    failures: &mut Vec<String>,
) -> String {
    let Statics {
        types,
        plugin,
        prefix,
    } = statics;
    let mut out =
        format!("{declaration} TABLES: SchemaTables = SchemaTables {{\n    schemas: &[\n");
    for schema in schemas {
        let kind = match schema.kind {
            SchemaKind::ConcreteTyped => "ConcreteTyped",
            SchemaKind::AbstractTyped => "AbstractTyped",
            SchemaKind::SingleApplyApi => "SingleApplyApi",
            SchemaKind::MultipleApplyApi => "MultipleApplyApi",
        };
        let _ = write!(
            out,
            "        Schema {{\n            name: {:?},\n            kind: SchemaKind::{kind},\n            \
             parent: {:?},\n            built_ins: &{:?},\n            properties: &[\n",
            schema.name, schema.parent, schema.built_ins
        );
        for property in &schema.properties {
            property_entry(
                &mut out,
                tokens,
                (plugin, prefix),
                &schema.name,
                property,
                types,
                failures,
            );
        }
        out.push_str("            ],\n            overrides: &[\n");
        for property in &schema.overrides {
            property_entry(
                &mut out,
                tokens,
                (plugin, prefix),
                &schema.name,
                property,
                types,
                failures,
            );
        }
        let _ = write!(
            out,
            "            ],\n            can_only_apply_to: &{:?},\n            \
             allowed_instance_names: &{:?},\n            instance_can_only_apply_to: &[",
            schema.can_only_apply_to, schema.allowed_instance_names
        );
        for (instance, types) in &schema.instance_can_only_apply_to {
            let _ = write!(out, "({instance:?}, &{types:?}), ");
        }
        out.push_str("],\n        },\n");
    }
    out.push_str("    ],\n    auto_applies: &[\n");
    for (schema, target) in auto_applies {
        let _ = writeln!(out, "        ({schema:?}, {target:?}),");
    }
    out.push_str("    ],\n    metadata: &[\n");
    for metadata in metadata {
        let name = tokens.resolve(metadata.name);
        let targets = metadata
            .targets
            .iter()
            .map(|target| format!("layerstack::MetadataTarget::{target:?}"))
            .collect::<Vec<_>>()
            .join(", ");
        let default = metadata
            .default
            .as_ref()
            .map(|value| expr(value, tokens).map(|value| format!("fallback({})", closure(&value))))
            .transpose()
            .unwrap_or_else(|why| {
                failures.push(format!("{name}: {why}"));
                None
            })
            .unwrap_or_else(|| "None".into());
        let _ = writeln!(
            out,
            "        Metadata {{ name: {name:?}, type_name: {:?}, targets: &[{targets}], default: {default}, display_group: {:?}, documentation: {:?} }},",
            metadata.value_type.name(),
            metadata.display_group,
            metadata.documentation
        );
    }
    out.push_str("    ],\n};\n");
    out
}

fn property_entry(
    out: &mut String,
    tokens: &TokenInterner,
    (plugin, prefix): (&'static str, &str),
    schema: &str,
    property: &Property,
    types: &mut ValueTypes,
    failures: &mut Vec<String>,
) {
    let kind = match property.kind {
        PropertyKind::Attribute => "Attribute",
        PropertyKind::Relationship => "Relationship",
    };
    let value_type = match &property.value_type {
        None => "None".to_string(),
        Some((name, is_array, _)) if layerstack::ValueType::from_name(name).is_some() => {
            format!("Some(&{prefix}{})", types.get(name, *is_array, plugin))
        }
        Some((name, ..)) => {
            failures.push(format!(
                "{schema}.{}: type {name}: not a registered value type",
                property.name
            ));
            "None".into()
        }
    };
    let fallback = match &property.fallback {
        None => "None".to_string(),
        Some(value) => match expr(value, tokens) {
            Ok(value) => format!("fallback({})", closure(&value)),
            Err(why) => {
                failures.push(format!("{schema}.{}: fallback: {why}", property.name));
                "None".into()
            }
        },
    };
    let metadata = property
        .metadata
        .iter()
        .filter_map(|field| {
            let name = tokens.resolve(field.name);
            match &field.value {
                layerstack::FieldValue::Value(value) => match expr(value, tokens) {
                    Ok(value) => Some(format!("({name:?}, {})", closure(&value))),
                    Err(why) => {
                        failures.push(format!(
                            "{schema}.{}: metadata {name}: {why}",
                            property.name
                        ));
                        None
                    }
                },
                _ => {
                    failures.push(format!(
                        "{schema}.{}: metadata {name}: list-op constructor unsupported",
                        property.name
                    ));
                    None
                }
            }
        })
        .collect::<Vec<_>>()
        .join(", ");
    let variability = match property.variability {
        Variability::Varying => "Varying",
        Variability::Uniform => "Uniform",
    };
    let _ = write!(
        out,
        "                Property {{\n                    name: {:?},\n                    \
         kind: PropertyKind::{kind},\n                    value_type: {value_type},\n                    \
         variability: Variability::{variability},\n                    fallback: {fallback},\n                    metadata: &[{metadata}],\n                \
         }},\n",
        property.name
    );
}

/// A closure constructing `expr` from the caller's token interner.
fn closure(expr: &str) -> String {
    if expr.contains("t.intern(") {
        format!("|t| {expr}")
    } else {
        format!("|_| {expr}")
    }
}

/// A Rust expression constructing `value`, whose tokens intern into `t`.
pub(crate) fn expr(value: &Value, tokens: &TokenInterner) -> Result<String, String> {
    fn list<T>(items: &[T], each: impl Fn(&T) -> String) -> String {
        let items: Vec<String> = items.iter().map(each).collect();
        format!("[{}]", items.join(", "))
    }
    Ok(match value {
        Value::Null => "Value::Null".into(),
        Value::Bool(v) => format!("Value::Bool({v})"),
        Value::UChar(v) => format!("Value::UChar({v})"),
        Value::Int(v) => format!("Value::Int({v})"),
        Value::UInt(v) => format!("Value::UInt({v})"),
        Value::Int64(v) => format!("Value::Int64({v})"),
        Value::UInt64(v) => format!("Value::UInt64({v})"),
        Value::Half(v) => format!("Value::Half({v:#06x})"),
        Value::Float(v) => format!("Value::Float({})", f32_lit(*v)),
        Value::Double(v) => format!("Value::Double({})", f64_lit(*v)),
        Value::String(v) => format!("Value::String(Arc::from({:?}))", &**v),
        Value::Token(v) => format!("Value::Token(t.intern({:?}))", tokens.resolve(*v)),
        Value::Asset(v) => format!("Value::Asset(Arc::from({:?}))", &**v),
        Value::PathExpression(v) => format!("Value::PathExpression(Arc::from({:?}))", &**v),
        Value::TimeCode(v) => format!("Value::TimeCode({})", f64_lit(*v)),
        Value::Duration(v) => format!("Value::Duration({})", f64_lit(*v)),
        Value::Vec2d(v) => format!("Value::Vec2d({})", list(v, |x| f64_lit(*x))),
        Value::Vec3d(v) => format!("Value::Vec3d({})", list(v, |x| f64_lit(*x))),
        Value::Vec4d(v) => format!("Value::Vec4d({})", list(v, |x| f64_lit(*x))),
        Value::Vec2f(v) => format!("Value::Vec2f({})", list(v, |x| f32_lit(*x))),
        Value::Vec3f(v) => format!("Value::Vec3f({})", list(v, |x| f32_lit(*x))),
        Value::Vec4f(v) => format!("Value::Vec4f({})", list(v, |x| f32_lit(*x))),
        Value::Vec2h(v) => format!("Value::Vec2h({})", list(v, |x| format!("{x:#06x}"))),
        Value::Vec3h(v) => format!("Value::Vec3h({})", list(v, |x| format!("{x:#06x}"))),
        Value::Vec4h(v) => format!("Value::Vec4h({})", list(v, |x| format!("{x:#06x}"))),
        Value::Vec2i(v) => format!("Value::Vec2i({})", list(v, ToString::to_string)),
        Value::Vec3i(v) => format!("Value::Vec3i({})", list(v, ToString::to_string)),
        Value::Vec4i(v) => format!("Value::Vec4i({})", list(v, ToString::to_string)),
        Value::Matrix2d(v) => format!(
            "Value::Matrix2d(alloc::boxed::Box::new({}))",
            list(&v[..], |x| f64_lit(*x))
        ),
        Value::Matrix3d(v) => format!(
            "Value::Matrix3d(alloc::boxed::Box::new({}))",
            list(&v[..], |x| f64_lit(*x))
        ),
        Value::Matrix4d(v) => format!(
            "Value::Matrix4d(alloc::boxed::Box::new({}))",
            list(&v[..], |x| f64_lit(*x))
        ),
        Value::Quatd(v) => format!("Value::Quatd({})", list(v, |x| f64_lit(*x))),
        Value::Quatf(v) => format!("Value::Quatf({})", list(v, |x| f32_lit(*x))),
        Value::Quath(v) => format!("Value::Quath({})", list(v, |x| format!("{x:#06x}"))),
        Value::TypedArray(items) => {
            let items = items
                .values()
                .map(|item| expr(&item, tokens))
                .collect::<Result<Vec<_>, _>>()?;
            // Generated fallback constructors keep their existing spelling;
            // runtime authored values may use either array representation.
            format!("Value::Array(alloc::vec![{}])", items.join(", "))
        }
        Value::Array(items) => {
            let items = items
                .iter()
                .map(|item| expr(item, tokens))
                .collect::<Result<Vec<_>, _>>()?;
            format!("Value::Array(alloc::vec![{}])", items.join(", "))
        }
        Value::Dictionary(entries) => {
            let entries = entries
                .iter()
                .map(|(key, item)| {
                    let item = item
                        .as_value()
                        .ok_or_else(|| format!("no constructor for {item:?}"))?;
                    Ok(format!(
                        "(Arc::from({:?}), {}.into())",
                        &**key,
                        expr(item, tokens)?
                    ))
                })
                .collect::<Result<Vec<_>, String>>()?;
            format!("Value::Dictionary(alloc::vec![{}])", entries.join(", "))
        }
        other => return Err(format!("no constructor for {other:?}")),
    })
}

fn f32_lit(v: f32) -> String {
    if v.is_nan() {
        "f32::NAN".into()
    } else if v.is_infinite() {
        if v > 0.0 {
            "f32::INFINITY"
        } else {
            "f32::NEG_INFINITY"
        }
        .into()
    } else {
        format!("{v:?}")
    }
}

fn f64_lit(v: f64) -> String {
    if v.is_nan() {
        "f64::NAN".into()
    } else if v.is_infinite() {
        if v > 0.0 {
            "f64::INFINITY"
        } else {
            "f64::NEG_INFINITY"
        }
        .into()
    } else {
        format!("{v:?}")
    }
}
